function validate([list1, list2]) {
  for (const [name, list] of [['list1', list1], ['list2', list2]]) {
    if (!Array.isArray(list) || list.length < 1 || list.length > 1000) return `${name} needs 1 to 1000 strings.`;
    if (list.some(s => typeof s !== 'string' || s.length < 1 || s.length > 30)) return `Each string in ${name} has 1 to 30 characters.`;
    if (list.some(s => !/^[A-Za-z ]+$/.test(s))) return `Strings in ${name} use only spaces and English letters.`;
    if (new Set(list).size !== list.length) return `The strings of ${name} must all be different.`;
  }
  const first = new Set(list1);
  if (!list2.some(s => first.has(s))) return 'list1 and list2 must share at least one string.';
  return null;
}

