function findRestaurant(list1, list2) {
  const indexOf = new Map();
  for (let i = 0; i < list1.length; i++) {
    indexOf.set(list1[i], i);
  }
  let bestSum = Infinity;
  let result = [];
  for (let j = 0; j < list2.length; j++) {
    if (j > bestSum) {
      break;
    }
    if (!indexOf.has(list2[j])) {
      continue;
    }
    const sum = indexOf.get(list2[j]) + j;
    if (sum < bestSum) {
      bestSum = sum;
      result = [list2[j]];
    } else if (sum === bestSum) {
      result.push(list2[j]);
    }
  }
  return result;
}

