function findRestaurant(list1, list2) {
  const pairs = [];
  for (let i = 0; i < list1.length; i++)
    for (let j = 0; j < list2.length; j++)
      if (list1[i] === list2[j]) pairs.push([list1[i], i + j]);
  const least = Math.min(...pairs.map(p => p[1]));
  return pairs.filter(p => p[1] === least).map(p => p[0]);
}

