function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const pick = list => list[Math.floor(rand() * list.length)];
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  let pool;
  if (size === 'large') {
    // The last word encodes the position, so every name is different.
    const words = ['Grill', 'Taco', 'Sushi', 'Burger', 'Pizza', 'Noodle', 'Cafe', 'House', 'King', 'Bar', 'Garden', 'Dragon', 'Golden', 'Blue', 'Tea', 'Deli'];
    pool = Array.from({ length: 1500 }, (_, i) => `${pick(words)} ${pick(words)} ${letters[i % 52]}${i >= 52 ? letters[Math.floor(i / 52)] : ''}`);
  } else {
    pool = shuffle(['a', 'b', 'c', 'A', 'Ab', 'ab', 'x y', 'xy', ' ', 'KFC', 'Tea', 'tea']).slice(0, 2 + Math.floor(rand() * 7));
  }
  const take = count => shuffle([...pool]).slice(0, count);
  const n1 = size === 'large' ? 1000 : 1 + Math.floor(rand() * pool.length);
  const n2 = size === 'large' ? 1000 : 1 + Math.floor(rand() * pool.length);
  const list1 = take(n1);
  let list2 = take(n2);
  const inFirst = new Set(list1);
  if (!list2.some(s => inFirst.has(s))) list2[Math.floor(rand() * list2.length)] = pick(list1);
  if (size === 'large' && rand() < 0.6) {
    // Put list1's first t strings at the front of list2 in reverse order: all t tie on index sum t - 1.
    const t = 2 + Math.floor(rand() * 5);
    const front = list1.slice(0, t);
    list2 = [...front.reverse(), ...list2.filter(s => !front.includes(s))].slice(0, 1000);
  }
  return [list1, list2];
}
